async def activate(q: asyncio.Queue, svc: OrderService, out: asyncio.Queue) -> None:
    while True:
        msg = await q.get()
        try:
            await out.put(await svc.place(msg))
        except Exception as exc:
            await errors.put((msg, exc))
        finally:
            q.task_done()          # ack only after the service finished
